import { MEMORY_SIZE, OPCODES, type OpcodeInfo } from '@vcpu/shared';
import fc from 'fast-check';
import { describe, expect, it } from 'vitest';
import {
  assemble,
  disassemble,
  labelsFromSymbols,
  toAssemblySource,
  type AssembleResult,
} from './index.js';

/** How a generated byte value is spelled in the source. */
type Spelling = 'dec' | 'neg' | 'hex' | 'bin' | 'char';

function spell(value: number, spelling: Spelling, allowNegative: boolean): string {
  if (spelling === 'neg' && allowNegative && value >= 0x80) return String(value - 0x100);
  if (spelling === 'hex') return `0x${value.toString(16)}`;
  if (spelling === 'bin') return `0b${value.toString(2)}`;
  if (spelling === 'char' && value >= 0x20 && value <= 0x7e && value !== 0x27 && value !== 0x5c) {
    return `'${String.fromCharCode(value)}'`;
  }
  return String(value);
}

interface GeneratedOperand {
  readonly register: number;
  readonly value: number;
  readonly spelling: Spelling;
  /** For jump/call targets: refer to the label of statement `target % count` instead. */
  readonly target: number | null;
}

type GeneratedStatement =
  | {
      readonly kind: 'instruction';
      readonly info: OpcodeInfo;
      readonly lowerCase: boolean;
      readonly operands: readonly GeneratedOperand[];
      readonly label: boolean;
    }
  | {
      readonly kind: 'bytes';
      readonly values: readonly [number, Spelling][];
      readonly label: boolean;
    }
  | { readonly kind: 'gap'; readonly size: number };

const spellingArb = fc.constantFrom<Spelling>('dec', 'neg', 'hex', 'bin', 'char');
const operandArb: fc.Arbitrary<GeneratedOperand> = fc.record({
  register: fc.integer({ min: 0, max: 7 }),
  value: fc.integer({ min: 0, max: 0xff }),
  spelling: spellingArb,
  target: fc.option(fc.nat(), { nil: null }),
});
const statementArb: fc.Arbitrary<GeneratedStatement> = fc.oneof(
  {
    weight: 8,
    arbitrary: fc.record({
      kind: fc.constant('instruction' as const),
      info: fc.constantFrom(...OPCODES),
      lowerCase: fc.boolean(),
      operands: fc.array(operandArb, { minLength: 2, maxLength: 2 }),
      label: fc.boolean(),
    }),
  },
  {
    weight: 1,
    arbitrary: fc.record({
      kind: fc.constant('bytes' as const),
      values: fc.array(fc.tuple(fc.integer({ min: 0, max: 0xff }), spellingArb), {
        minLength: 1,
        maxLength: 4,
      }),
      label: fc.boolean(),
    }),
  },
  { weight: 1, arbitrary: fc.record({ kind: fc.constant('gap' as const), size: fc.nat(6) }) },
);

/** Renders generated statements as source, dropping whatever would not fit in memory. */
function render(statements: readonly GeneratedStatement[]): string {
  const lines: string[] = [];
  const labelOf = (index: number): string => `L${String(index)}`;
  const labelled = statements.flatMap((statement, index) =>
    statement.kind !== 'gap' && statement.label ? [index] : [],
  );
  let lc = 0;
  for (const [index, statement] of statements.entries()) {
    const size =
      statement.kind === 'instruction'
        ? statement.info.length
        : statement.kind === 'bytes'
          ? statement.values.length
          : statement.size;
    if (lc + size > MEMORY_SIZE) break;
    lc += size;
    if (statement.kind === 'gap') {
      lines.push(`.org ${String(lc)}`);
      continue;
    }
    const prefix = statement.label ? `${labelOf(index)}: ` : '';
    if (statement.kind === 'bytes') {
      const values = statement.values.map(([value, spelling]) => spell(value, spelling, true));
      lines.push(`${prefix}.byte ${values.join(', ')}`);
      continue;
    }
    const { info, lowerCase } = statement;
    const operands = info.operands.map((spec, i) => {
      const operand = statement.operands[i] ?? {
        register: 0,
        value: 0,
        spelling: 'dec',
        target: null,
      };
      // Mnemonics and registers are case-insensitive; labels are not, so they keep their case.
      const register = `${lowerCase ? 'r' : 'R'}${String(operand.register)}`;
      switch (spec.kind) {
        case 'reg':
          return register;
        case 'regIndirect':
          return `[${register}]`;
        case 'imm8':
          return spell(operand.value, operand.spelling, true);
        case 'addr8': {
          const targetIndex =
            operand.target === null || labelled.length === 0
              ? null
              : labelled[operand.target % labelled.length];
          const value =
            spec.role === 'target' && targetIndex !== undefined && targetIndex !== null
              ? labelOf(targetIndex)
              : spell(operand.value, operand.spelling === 'char' ? 'hex' : operand.spelling, false);
          return spec.role === 'addr' ? `[${value}]` : value;
        }
      }
    });
    const mnemonic = lowerCase ? info.mnemonic.toLowerCase() : info.mnemonic;
    lines.push(prefix + [mnemonic, operands.join(', ')].join(' ').trim());
  }
  return lines.join('\n');
}

/** Disassembles every used range of an assembled program and reassembles the listing. */
function reassemble(first: AssembleResult): { source: string; second: AssembleResult } {
  const labels = labelsFromSymbols(first.symbols);
  const lines = first.bytes.ranges.flatMap((range) =>
    disassemble(first.bytes.image, { start: range.start, end: range.end, labels }),
  );
  const source = toAssemblySource(lines, labels);
  return { source, second: assemble(source) };
}

describe('round trip: assemble → disassemble → reassemble', () => {
  it('reproduces 1,000 random valid programs byte for byte', () => {
    fc.assert(
      fc.property(
        fc.array(statementArb, { minLength: 1, maxLength: 90, size: 'max' }),
        (statements) => {
          const source = render(statements);
          const first = assemble(source);
          expect(first.diagnostics, source).toEqual([]);
          const { source: listing, second } = reassemble(first);
          expect(second.diagnostics, listing).toEqual([]);
          expect(second.bytes.ranges).toEqual(first.bytes.ranges);
          expect(Array.from(second.bytes.image)).toEqual(Array.from(first.bytes.image));
        },
      ),
      { numRuns: 1000 },
    );
  });

  it('reassembles the disassembly of arbitrary memory to the same bytes', () => {
    fc.assert(
      fc.property(
        fc.uint8Array({ minLength: 1, maxLength: MEMORY_SIZE }),
        fc.nat(MEMORY_SIZE - 1),
        (bytes, offset) => {
          const start = offset % bytes.length;
          const lines = disassemble(bytes, { start });
          expect(lines.flatMap((line) => line.bytes)).toEqual(Array.from(bytes.slice(start)));
          const result = assemble(toAssemblySource(lines));
          expect(result.diagnostics).toEqual([]);
          expect(Array.from(result.bytes.image.slice(start, bytes.length))).toEqual(
            Array.from(bytes.slice(start)),
          );
        },
      ),
      { numRuns: 500 },
    );
  });
});
